/**
 * @helios/oui — motion 层(可选,基于 anime.js v4)
 *
 * 设计原则(anthropic frontend-design):
 *   • motion 要 deliberate:编排的入场 > 散落的效果
 *   • less is more:不需要的地方不要动画
 *   • reduced-motion 必须尊重
 *
 * anime.js 是 optionalDependency:
 *   • 装了 → 用 anime.js 做高级编排(stagger/timeline/spring)
 *   • 没装 → 降级,函数变 no-op 或回退 CSS,不报错
 *
 * 用法:
 *   import { staggerReveal, animateValue } from '@helios/oui/motion';
 *   staggerReveal('.card', { delay: 60 });          // 列表交错入场
 *   animateValue(el, { from: 0, to: 48392 });        // 数字滚动
 */

type AnimeModule = typeof import('animejs');

let _anime: AnimeModule | null = null;
let _animePromise: Promise<AnimeModule | null> | null = null;

/**
 * 懒加载 anime.js,失败返回 null(未安装)。
 * 缓存 promise(而非结果):并发调用共享同一次 import,
 * 避免"首个调用 import 进行中、后续调用拿到 null"的竞态(否则多个同时动画只有第一个生效)。
 */
async function loadAnime(): Promise<AnimeModule | null> {
  if (_animePromise) return _animePromise;
  _animePromise = import('animejs')
    .then((m) => { _anime = m; return _anime; })
    .catch(() => { _anime = null; return null; });
  return _animePromise;
}

/** 是否尊重 reduced-motion */
function prefersReducedMotion(): boolean {
  return typeof window !== 'undefined'
    && window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
}

export interface StaggerRevealOptions {
  /** 每个元素间隔 ms,默认 60 */
  delay?: number;
  /** 单元素时长 ms,默认 500 */
  duration?: number;
  /** 从哪个方向交错:'first' | 'last' | 'center',默认 'first' */
  from?: 'first' | 'last' | 'center';
  /** Y 位移起点 px,默认 12 */
  translateY?: number;
}

/**
 * 列表交错入场 — 编排式,比散落的单个 fade 更"deliberate"
 * 降级:reduced-motion 或未装 anime.js 时,直接显示(无动画)
 */
export async function staggerReveal(
  target: string | HTMLElement | HTMLElement[],
  opts: StaggerRevealOptions = {}
): Promise<void> {
  if (prefersReducedMotion()) return;
  const anime = await loadAnime();
  if (!anime) return;  // 未装 → no-op(元素保持可见)

  const { delay = 60, duration = 500, from = 'first', translateY = 12 } = opts;
  anime.animate(target, {
    opacity: { from: 0, to: 1 },
    translateY: { from: translateY, to: 0 },
    delay: anime.stagger(delay, { from }),
    duration,
    ease: 'out(3)',
  });
}

export interface AnimateValueOptions {
  from?: number;
  to: number;
  duration?: number;
  /** 格式化,如千分位 */
  format?: (v: number) => string;
}

/**
 * 数字滚动动画 — KPI/metric 用
 * 降级:未装 anime.js 时直接设最终值
 */
export async function animateValue(
  el: HTMLElement,
  opts: AnimateValueOptions
): Promise<void> {
  const { from = 0, to, duration = 1200, format = (v) => Math.round(v).toLocaleString() } = opts;
  if (prefersReducedMotion()) { el.textContent = format(to); return; }
  const anime = await loadAnime();
  if (!anime) { el.textContent = format(to); return; }

  const obj = { v: from };
  anime.animate(obj, {
    v: to,
    duration,
    ease: 'out(4)',
    onUpdate: () => { el.textContent = format(obj.v); },
  });
}

/**
 * 页面/区块入场编排 timeline
 * 降级:未装时 no-op
 */
export async function orchestrate(
  steps: Array<{ target: string | HTMLElement; props: Record<string, unknown>; at?: string | number }>
): Promise<void> {
  if (prefersReducedMotion()) return;
  const anime = await loadAnime();
  if (!anime) return;

  const tl = anime.createTimeline({ defaults: { duration: 500, ease: 'out(3)' } });
  for (const s of steps) {
    // anime.js 为动态加载的可选增强库,add() 有多重载;编排步骤 props 是运行时开放字典。
    // 在此动态派发边界用宽松签名调用(不影响运行时,仅规避重载类型歧义)。
    (tl.add as (...a: unknown[]) => unknown)(s.target, s.props, s.at);
  }
}

/** 是否可用 anime.js(已安装且非 reduced-motion) */
export async function motionAvailable(): Promise<boolean> {
  if (prefersReducedMotion()) return false;
  return (await loadAnime()) !== null;
}
